export const title = "How to Set Up Two Video-Call Workstations in One Room";
export const metaTitle = "How to Set Up Two Video-Call Workstations in";
export const metaDescription = "Plan two video-call workstations in one room with checks for microphone pickup, speaker output, and shared routines. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
